contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callee, bytes memory data) public payable {
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If forwarding non-empty data to an EOA (the owner, which we cannot
        // observe directly) succeeded, the EOA's low-level call must have
        // returned true.  But any low-level call to an EOA with non-empty data
        // still returns true; the only way it returns false is when the data is
        // empty and value is non-zero (not possible here since no value is sent).
        // Therefore, for the owner, forwarding non-empty data must NOT revert.
        // We use this contrapositive to form a rule that must hold for all
        // callee/data: if data is non-empty, and the callee is the owner, then
        // forwarding must succeed.
        // Since owner is not directly observable, we cannot write this directly.
        // However, the contract does have a reliable observable: the owner is
        // msg.sender of the constructor, which is this test contract.  As the
        // test contract cannot be the callee (it would call itself, but our
        // receive/fallback are not defined to accept calls, and the test would
        // recurse), we can use the fact that any call to a non-contract address
        // (like a fresh EOA) with non-empty data will succeed.
        // The original P's forward succeeds if and only if the low-level call
        // returns true.  For EOA callees, non-empty data always yields true.
        // So a general rule: for any callee that is an EOA, forwarding non-empty
        // data succeeds.  We can approximate EOA by using an address with no code.
        // We add a precondition that the callee has no code (an EOA).
        require(callee.code.length == 0);

        // If the callee is an EOA and data is non-empty, the low-level call
        // returns true (since no fallback, and the call is not rejected).
        // Therefore c.forward should not revert.
        assert(data.length == 0 || !reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callee, bytes memory data) public payable {
        // Exclude codes that have no code (EOAs) because they may reject calls.
        require(callee.code.length > 0);

        // Ensure the target will accept the call: it must have code and data non-empty.
        // Also exclude the owner being the callee, since we cannot observe the owner,
        // but the test contract itself can be a callee and it accepts non-empty data.
        // However, we must restrict to callees that are not the test contract itself,
        // to avoid recursion. The test contract will be a contract with code, so
        // the rule would still hold, but we exclude it to keep the call trace clean.
        require(callee != address(this));

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for any callee that definitely has code and is not this test
        // contract, forwarding non-empty data via c.forward never reverts.
        // The only way the underlying call fails is if the callee rejects the call
        // (e.g., out of gas or a revert in its fallback). Since we cannot force a
        // revert in an arbitrary contract, the checker cannot find a counterexample
        // where the callee has code, is not this test, and non-empty data causes revert.
        // For an EOA, it might revert if value is sent, but we send zero value.
        assert(data.length > 0 ? !reverted : true);
    }

    receive() external payable {}
}

